# ── Helpers for these stages ──────────────────────────────────────────────

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# require ask|ask_secret KEY "Prompt" — like ask, but insists on a value.
require() {
  local fn="$1" key="$2" prompt="$3"
  while true; do
    "$fn" "$key" "$prompt"
    [[ -n "${!key}" ]] && return 0
    warn "a value is required"
  done
}

# ask_date KEY "Prompt" — insists on a YYYY-MM-DD date.
ask_date() {
  local key="$1" prompt="$2"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] && return 0
    warn "expected a date as YYYY-MM-DD"
  done
}

# The credentials go through curl's stdin config, never its command line, so they don't show in `ps`.

# basic_status EMAIL TOKEN PATH — HTTP status of a GET with an API token.
basic_status() {
  printf 'user = "%s:%s"\n' "$1" "$2" \
    | curl -sS -K - -o /dev/null -w '%{http_code}' "$API$3" 2>/dev/null || true
}

# basic_get EMAIL TOKEN PATH — body of a GET with an API token.
basic_get() {
  printf 'user = "%s:%s"\n' "$1" "$2" | curl -sS -K - "$API$3" 2>/dev/null || true
}

# bearer_status TOKEN PATH — HTTP status of a GET with an access token.
bearer_status() {
  printf 'header = "Authorization: Bearer %s"\n' "$1" \
    | curl -sS -K - -o /dev/null -w '%{http_code}' "$API$2" 2>/dev/null || true
}

# expect EXPECTED "what" COMMAND... — runs COMMAND until it prints EXPECTED, or the human gives up.
expect() {
  local expected="$1" what="$2" actual
  shift 2
  while true; do
    actual=$("$@")
    if [[ "$actual" == "$expected" ]]; then
      ok "$what"
      return 0
    fi
    warn "$what — got '${actual:-nothing}', expected '$expected'"
    note "A wrong value? Answer N, let the wizard finish, and re-run it: Enter keeps the other values."
    if ! confirm "Fixed it in the browser — check again?"; then
      SKIPPED+=("check failed: $what")
      return 0
    fi
  done
}

repo_path() {
  printf '/2.0/repositories/%s/%s' "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_WORKSPACE" "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_REPOSITORY"
}

bot_status() {
  basic_status "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_EMAIL" "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_TOKEN" "$1"
}

approver_status() {
  basic_status "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_APPROVER_EMAIL" "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_APPROVER_TOKEN" "$1"
}

repository_project() {
  basic_get "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_EMAIL" "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_TOKEN" "$(repo_path)" \
    | grep -Eo '"project": *\{[^}]*"key": *"[^"]*"' | grep -Eo '"key": *"[^"]*"' | sed -E 's/.*"([^"]*)"$/\1/' || true
}

pipelines_state() {
  if basic_get "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_EMAIL" "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_TOKEN" "$(repo_path)/pipelines_config" \
    | grep -Eq '"enabled": *true'; then
    echo enabled
  else
    echo disabled
  fi
}

upload_fixture() {
  local status
  status=$(printf 'user = "%s:%s"\n' "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_EMAIL" "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_TOKEN" \
    | curl -sS -K - -o /dev/null -w '%{http_code}' -X POST "$API$(repo_path)/src" \
        -F "gradle.properties=@$FIXTURE_DIR/gradle.properties" \
        -F "bitbucket-pipelines.yml=@$FIXTURE_DIR/bitbucket-pipelines.yml" \
        -F "message=Yontrack test fixture" \
        -F "branch=main" 2>/dev/null || true)
  if [[ "$status" == "201" ]]; then
    ok "fixture committed on main"
  else
    warn "upload failed with HTTP ${status:-nothing} — the bot token needs write:repository:bitbucket"
    SKIPPED+=("upload of the fixture content")
  fi
}

