say "The Bearer identity (ACCESS_TOKEN configurations). Every plan has repository access tokens;"
say "workspace and project access tokens need Premium."
open_url "https://bitbucket.org/$(repo_path | sed 's|^/2.0/repositories/||')/admin/access-tokens"
step "In the bot's window: Repository settings → Security → Access tokens → Create access token."
step "Name: yontrack-tests. Expiry: the latest date offered (No expiry, if the workspace allows it)."
step "Permissions:"
note "    Repositories: Read, Write"
note "    Pull requests: Read, Write"
note "    Pipelines: Read, Write"
step "Create, and copy the token — it is shown only once."
require ask_secret ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN "Repository access token:"
ask_date ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN_EXPIRY "Its expiry date (YYYY-MM-DD; 9999-12-31 for No expiry):"
write_env ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN"
write_env ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN_EXPIRY "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN_EXPIRY"
expect 200 "the access token reads the repository" bearer_status "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN" "$(repo_path)"
expect 200 "the access token reads the pull requests" bearer_status "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN" "$(repo_path)/pullrequests"
expect 200 "the access token reads the pipelines" bearer_status "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN" "$(repo_path)/pipelines/"
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Token expiry"
TOKENS_EXPIRY=$(printf '%s\n' \
  "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_BOT_TOKEN_EXPIRY" \
  "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_APPROVER_TOKEN_EXPIRY" \
  "$ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_ACCESS_TOKEN_EXPIRY" | sort | sed -n 1p)
write_env "$EXPIRY_VAR" "$TOKENS_EXPIRY"
say "The first token to expire does so on ${BOLD}$TOKENS_EXPIRY${RESET}."
say "From two weeks before that date, BitbucketCloudTestWorkspaceIT fails and asks for a renewal."
if grep -q '<!-- tokens-expiry -->' "$README"; then
  tmp=$(mktemp)
  sed -E "s|(<!-- tokens-expiry -->).*(<!-- /tokens-expiry -->)|\1${TOKENS_EXPIRY}\2|" "$README" > "$tmp"
  mv "$tmp" "$README"
  ok "README: renewal date set to $TOKENS_EXPIRY"
  step "Commit ontrack-extension-bitbucket-cloud/README.md once the wizard is done."
else
  warn "no tokens-expiry marker in $README — record $TOKENS_EXPIRY there by hand"
fi
step "Put a reminder in a calendar a month before $TOKENS_EXPIRY: re-run this wizard."
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "GitHub secrets"
say "The integration shard of .github/workflows/ci.yml reads these secrets from $GH_REPO:"
for name in $SECRETS; do step "$name"; done
say "and this variable, which is no secret:"
step "$EXPIRY_VAR = $TOKENS_EXPIRY"
if confirm "Write them to $GH_REPO now (existing values are replaced)?"; then
  for name in $SECRETS; do set_secret "$name" "${!name}"; done
  set_var "$EXPIRY_VAR" "$TOKENS_EXPIRY"
else
  SKIPPED+=("GitHub secrets and the $EXPIRY_VAR variable")
fi
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Retire the app-password secrets"
say "Atlassian removed app passwords on 2026-07-28. These secrets hold one and nothing reads them any more:"
for name in $DEAD_SECRETS; do step "$name"; done
note "ONTRACK_TEST_EXTENSION_BITBUCKET_CLOUD_WORKSPACE stays: the previous stage replaced its value."
if gh_ready; then
  printf '  %sDeleting a secret cannot be undone.%s\n' "$RED" "$RESET"
  if confirm "Delete these two secrets from $GH_REPO?"; then
    for name in $DEAD_SECRETS; do
      if gh secret delete "$name" >/dev/null 2>&1; then ok "deleted $name"; else warn "could not delete $name (already gone?)"; fi
    done
  else
    SKIPPED+=("deletion of the app-password secrets: gh secret delete <name>")
  fi
  say ""
  say "Bitbucket Cloud secrets and variables now in $GH_REPO:"
  gh secret list | grep BITBUCKET_CLOUD | sed 's/^/    /' || true
  gh variable list | grep BITBUCKET_CLOUD | sed 's/^/    /' || true
else
  SKIPPED+=("deletion of the app-password secrets: gh secret delete <name>")
fi
pause

finish

say "Run the real tests locally with:"
note "  set -a; source $ENV_FILE; set +a"
note "  ./gradlew :ontrack-extension-bitbucket-cloud:integrationTest"
say "In CI, dispatch the CI workflow with SKIP_BITBUCKET_CLOUD_IT unticked."
printf '\n'
